/**
 * @distilled.cloud/turbopuffer — turbopuffer SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * spec). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as Turbopuffer from "@distilled.cloud/turbopuffer";
 *
 * const namespaces = yield* Turbopuffer.Services.turbopuffer.getV1Namespaces({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  TurbopufferProtocol,
  type TurbopufferOpError,
  type TurbopufferOpContext,
} from "./protocol.ts";
